properties.query:
// Genuinely legacy/basic-auth protocol identifiers only. AutoDiscover and
// "Exchange Web Services" are deliberately excluded: modern OAuth clients emit
// them too (Outlook for Mac, third-party EWS integrations), so including them
// produced false positives on healthy estates without adding detection value.
// Add them back via the tuning guidance only if your tenant still fronts EWS
// with basic auth.
let legacy_clients = dynamic([
  "Other clients; POP",
  "Other clients; IMAP",
  "Other clients; SMTP",
  "Other clients; MAPI",
  "Other clients; Exchange ActiveSync",
  "Authenticated SMTP"
]);
let excluded_users = dynamic([]);
SigninLogs
| where TimeGenerated > ago(1h)
| where ResultType == 0
| where ClientAppUsed in (legacy_clients)
| where UserPrincipalName !in (excluded_users)
| project TimeGenerated, UserPrincipalName, IPAddress, ClientAppUsed,
          AppDisplayName, UserAgent, Location
